/**
 * Helpers that describe a gated action to its approver. Nothing here decides
 * allow, gate or block: a wrong answer can only make the description less
 * informative, never change what runs. Output is plain text because each
 * harness shows it in its own approval surface (a native permission prompt, a
 * chat card, a hand-off message).
 */
import { readFileSync, statSync } from 'fs';
import { parse } from 'unbash';

// Short enough for the tightest known surface: NanoClaw posts it into a
// 3000-character Slack block next to its own 1400-character command preview.
export const CARD_SUMMARY_MAX_CHARS = 1300;
export const CARD_LABEL_MAX_CHARS = 130;

const BODY_FILE_MAX_BYTES = 256 * 1024;

export function clip(text: string, max: number): string {
    const chars = Array.from(text);
    if (chars.length <= max) return text;
    return chars.slice(0, Math.max(0, max - 1)).join('').trimEnd() + '…';
}

export function oneLine(text: string): string {
    return text.replace(/\s+/g, ' ').trim();
}

/** Inline code cannot contain a backtick in chat markdown; swap it so the span stays closed. */
export function code(text: string): string {
    return '`' + text.replace(/`/g, 'ʼ') + '`';
}

/** Quote untrusted text; `<!channel>`, `<@U…>` and `<#C…>` would ping or link when a harness posts it to Slack. */
export function quoteBlock(text: string): string {
    return text.replace(/<(?=[!@#])/g, '‹').split('\n').map(line => `> ${line}`).join('\n');
}

/** What a shell variable holds at a point in a command, as far as the text shows. */
export type ShellValue =
    | { kind: 'text'; value: string }
    | { kind: 'file'; path: string }
    | { kind: 'runtime' };

export interface ShellCommand {
    name: string;
    args: string[];
    pos: number;
}

export interface ShellView {
    commands: ShellCommand[];
    valueAt(name: string, pos: number): ShellValue | undefined;
}

function walk(node: unknown, visit: (n: any) => void, seen = new WeakSet<object>()): void {
    if (!node || typeof node !== 'object' || seen.has(node as object)) return;
    seen.add(node as object);
    if (Array.isArray(node)) {
        for (const child of node) walk(child, visit, seen);
        return;
    }
    visit(node);
    for (const child of Object.values(node as Record<string, unknown>)) walk(child, visit, seen);
}

const VAR_REF = /\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))/g;

function catFileOf(script: any): string | null {
    const commands: any[] = [];
    walk(script, n => { if (n.type === 'Command') commands.push(n); });
    if (commands.length !== 1) return null;
    const [cmd] = commands;
    const args = (cmd.suffix || []).map((s: any) => s.value ?? s.text ?? '');
    if (cmd.name?.value !== 'cat' || args.length !== 1 || (cmd.prefix || []).length) return null;
    return args[0].startsWith('/') ? args[0] : null;
}

/** Remove shell quoting from a word; null when it contains an expansion. */
function unquoteWord(word: string): string | null {
    let out = '';
    let i = 0;
    while (i < word.length) {
        const c = word[i];
        if (c === "'") {
            const close = word.indexOf("'", i + 1);
            if (close < 0) return null;
            out += word.slice(i + 1, close);
            i = close + 1;
        } else if (c === '"') {
            i++;
            while (i < word.length && word[i] !== '"') {
                if (word[i] === '$' || word[i] === '`') return null;
                if (word[i] === '\\' && i + 1 < word.length && '"\\$`\n'.includes(word[i + 1])) i++;
                out += word[i++];
            }
            if (i >= word.length) return null;
            i++;
        } else if (c === '$' || c === '`') {
            return null;
        } else {
            if (c === '\\') i++;
            out += word[i++] ?? '';
        }
    }
    return out;
}

/**
 * Parse `command` into its simple commands and the literal variable assignments
 * that precede each one. A value built from anything but literal text, other
 * resolved variables, or `$(cat /absolute/path)` is reported as `runtime`.
 */
export function viewShell(command: string): ShellView {
    const assignments: Array<{ name: string; pos: number; value: ShellValue }> = [];
    const commands: ShellCommand[] = [];
    let ast: any;
    try {
        ast = parse(command);
    } catch {
        return { commands, valueAt: () => undefined };
    }

    const valueAt = (name: string, pos: number): ShellValue | undefined => {
        let latest: ShellValue | undefined;
        for (const a of assignments) if (a.name === name && a.pos < pos) latest = a.value;
        return latest;
    };

    const valueOf = (word: any, pos: number): ShellValue => {
        const parts: any[] = word?.parts;
        if (!Array.isArray(parts)) {
            // unbash leaves a multi-line quoted word unsplit, quotes included.
            const value = unquoteWord(String(word?.text ?? word?.value ?? ''));
            return value === null ? { kind: 'runtime' } : { kind: 'text', value };
        }
        if (parts.length === 1 && parts[0]?.type === 'CommandExpansion') {
            const path = catFileOf(parts[0].script);
            return path ? { kind: 'file', path } : { kind: 'runtime' };
        }
        let out = '';
        const flat = parts.flatMap((p: any) => (p?.type === 'DoubleQuoted' ? p.parts ?? [] : [p]));
        for (const p of flat) {
            if (p?.type === 'Literal' || p?.type === 'SingleQuoted' || p?.type === 'AnsiCQuoted') {
                out += p.value ?? '';
            } else if (p?.type === 'SimpleExpansion' || p?.type === 'ParameterExpansion') {
                const ref = String(p.text ?? '').match(/^\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?$/);
                const inner = ref ? valueAt(ref[1], pos) : undefined;
                if (inner?.kind !== 'text') return { kind: 'runtime' };
                out += inner.value;
            } else {
                return { kind: 'runtime' };
            }
        }
        return { kind: 'text', value: out };
    };

    const nodes: any[] = [];
    walk(ast, n => { if (n.type === 'Assignment' || n.type === 'Command') nodes.push(n); });
    nodes.sort((a, b) => (a.pos ?? 0) - (b.pos ?? 0));
    for (const n of nodes) {
        const pos = typeof n.pos === 'number' ? n.pos : 0;
        if (n.type === 'Assignment') {
            if (typeof n.name === 'string') assignments.push({ name: n.name, pos, value: valueOf(n.value, pos) });
            continue;
        }
        if (!n.name) continue;
        const args = (n.suffix || []).map((s: any) => String(s.value ?? s.text ?? ''));
        const name = String(n.name.value ?? n.name.text ?? '');
        if (name === 'export' || name === 'declare') {
            for (const arg of args) {
                const m = arg.match(/^([A-Za-z_][A-Za-z0-9_]*)=([\s\S]*)$/);
                if (m) assignments.push({ name: m[1], pos, value: /\$/.test(m[2]) ? { kind: 'runtime' } : { kind: 'text', value: m[2] } });
            }
        }
        commands.push({ name, args, pos });
    }
    return { commands, valueAt };
}

/**
 * Substitute variables whose literal value the command itself sets. Returns the
 * names it could not resolve so the card can say they are decided at run time.
 */
export function expandKnown(text: string, view: ShellView, pos: number): { text: string; unresolved: string[] } {
    const unresolved: string[] = [];
    const out = text.replace(VAR_REF, (whole, braced, bare) => {
        const name = braced ?? bare;
        const value = view.valueAt(name, pos);
        if (value?.kind === 'text') return value.value;
        if (!unresolved.includes(whole)) unresolved.push(whole);
        return whole;
    });
    return { text: out, unresolved };
}

/** Read a file the agent can already read, for display only. Null when absent or too big. */
export function readDisplayFile(path: string): string | null {
    try {
        if (!path.startsWith('/')) return null;
        const st = statSync(path);
        if (!st.isFile() || st.size > BODY_FILE_MAX_BYTES) return null;
        return readFileSync(path, 'utf8');
    } catch {
        return null;
    }
}

const ENTITIES: Record<string, string> = {
    amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
    mdash: '—', ndash: '–', hellip: '…', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“', bull: '•',
};

function decodeEntities(text: string): string {
    return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (whole, ent: string) => {
        if (ent[0] === '#') {
            const n = ent[1] === 'x' || ent[1] === 'X' ? parseInt(ent.slice(2), 16) : parseInt(ent.slice(1), 10);
            return Number.isFinite(n) && n > 0 && n < 0x110000 ? String.fromCodePoint(n) : whole;
        }
        return ENTITIES[ent.toLowerCase()] ?? whole;
    });
}

/** Render an HTML email body as the plain text a recipient would read. */
export function htmlToText(html: string): string {
    const text = html
        .replace(/<(script|style|head)\b[\s\S]*?<\/\1>/gi, '')
        .replace(/<!--[\s\S]*?-->/g, '')
        .replace(/<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (_w, href: string, label: string) => {
            const inner = label.replace(/<[^>]+>/g, '').trim();
            return inner && inner !== href ? `${inner} (${href})` : href;
        })
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<li\b[^>]*>/gi, '\n• ')
        .replace(/<\/(p|div|h[1-6]|tr|table|ul|ol|blockquote)>/gi, '\n\n')
        .replace(/<(p|div|h[1-6]|tr|table|ul|ol|blockquote)\b[^>]*>/gi, '\n')
        .replace(/<\/(td|th)>/gi, '\t')
        .replace(/<[^>]+>/g, '');
    return decodeEntities(text)
        .replace(/[ \t]+\n/g, '\n')
        .replace(/\n[ \t]+/g, '\n')
        .replace(/[ \t]{2,}/g, ' ')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
}

/** Join card lines, dropping trailing lines (not cutting mid-line) once over budget. */
export function fitLines(lines: string[], max = CARD_SUMMARY_MAX_CHARS): string {
    const out: string[] = [];
    let used = 0;
    for (const line of lines) {
        const len = Array.from(line).length + 1;
        if (used + len > max) {
            const cut = clip(line, Math.max(40, max - used - 2));
            out.push((cut.match(/`/g) ?? []).length % 2 ? cut + '`' : cut);
            break;
        }
        out.push(line);
        used += len;
    }
    return out.join('\n');
}
